<script>
import gql from "graphql-tag"
import { mapGetters } from "vuex"

import Layout from "@/components/layout/Layout"

export default {
	name: "Settings",
	metaInfo: {
		title: "Configuración"
	},
	components: {
		Layout
	},
	computed: {
		...mapGetters(["isAuthenticated", "loggedMedic"])
	},
	data() {
		return {
			medic: {},
			validationErrors: {},
			loading: true
		}
	},
	methods: {
		deleteAddressConfirm(id) {
			this.$dialog.confirm("¿Está seguro que desea eliminar esta dirección?").then(() => {
				this.deleteAddress(id)
			})
		},
		deleteAddress(id) {
			this.validationErrors = {}
			let error = false
			if (this.medic.medicBusinessAddresses.length <= 1) {
				this.$toast.error("No se puede eliminar, debes tener al menos una dirección ingresada")
				error = true
			}

			if (!error && !this.loading) {
				this.loading = true
				this.$apollo
					.mutate({
						mutation: gql`
							mutation($id: ID!) {
								medicBusinessAddressDelete(id: $id) {
									id
								}
							}
						`,
						variables: {
							id: id
						}
					})
					.then(() => {
						this.$toast.success("Dirección eliminada correctamente")
						this.loading = false
						this.$apollo.queries.meMedic.refetch()
						this.hasChanges = false
					})
					.catch(error => {
						this.$toast.error("Error al eliminar la dirección!")
						let { graphQLErrors } = error
						if (graphQLErrors[0].extensions.category === "validation") {
							this.validationErrors = this.parseErrors(graphQLErrors[0].extensions.validation)
						} else {
							this.validationErrors["general"] = "Se ha producido un error"
						}
						this.loading = false
					})
			}
		}
	},
	apollo: {
		meMedic: {
			query: gql`
				query {
					medicLogged {
						id
						name
						lastname
						email
						birthdate
						cjp
						phone {
							national
							international
						}
						document {
							type
							number
						}
						address {
							country {
								id
								name
							}
							city
							neighborhood
							street
						}
					}
				}
			`,
			fetchPolicy: "no-cache",
			result({ data }) {
				this.medic = data.medicLogged
				this.loading = false
			}
		}
	}
}
</script>

